-- Enterprise data quality management capability: logical data model as PostgreSQL DDL (model version 1.1.0).
-- Generated by scripts/build_models.py from models/dq-capability.yaml. Do not edit by hand.
-- Holds roles, not personal contact details: a named data owner is a role holder, and contact routes are forms.

CREATE TABLE organisation (
  organisation_id text PRIMARY KEY,
  name text NOT NULL,
  organisation_type text,
  nation text,
  parent_organisation text REFERENCES organisation(organisation_id)
);
COMMENT ON TABLE organisation IS 'A department, arm''s length body or other organisation that holds, provides or uses data.';
COMMENT ON COLUMN organisation.organisation_id IS 'Identifier, ideally the GOV.UK organisation slug';
COMMENT ON COLUMN organisation.name IS 'Organisation name as listed on GOV.UK';
COMMENT ON COLUMN organisation.organisation_type IS 'Department, ALB, local authority, devolved body and so on';
COMMENT ON COLUMN organisation.nation IS 'Nation or jurisdiction';
COMMENT ON COLUMN organisation.parent_organisation IS 'Sponsoring department for an ALB';

CREATE TABLE data_asset (
  asset_id text PRIMARY KEY,
  title text NOT NULL,
  alternative_title text,
  description text NOT NULL,
  creator text REFERENCES organisation(organisation_id) NOT NULL,
  is_critical boolean NOT NULL,
  date_created date NOT NULL,
  expires date,
  superseded_by text REFERENCES data_asset(asset_id),
  temporal_coverage text,
  conforms_to text,
  access_rights text CHECK (access_rights IN ('Open', 'Commercial', 'Internal')) NOT NULL,
  security_classification text CHECK (security_classification IN ('OFFICIAL')) NOT NULL,
  licence text NOT NULL,
  source_dataset text REFERENCES data_asset(asset_id),
  catalogue_url text,
  last_metadata_review date,
  next_review date
);
COMMENT ON TABLE data_asset IS 'A critical data asset, or any data set managed by the capability.';
COMMENT ON COLUMN data_asset.asset_id IS 'Unique identifier (MD identifier)';
COMMENT ON COLUMN data_asset.title IS 'Plain English name (MD title)';
COMMENT ON COLUMN data_asset.creator IS 'Creating organisation (MD creator)';
COMMENT ON COLUMN data_asset.is_critical IS 'Designated as a critical data asset';
COMMENT ON COLUMN data_asset.date_created IS 'ISO 8601 (MD dateCreated)';
COMMENT ON COLUMN data_asset.expires IS 'MD expires';
COMMENT ON COLUMN data_asset.superseded_by IS 'MD supersededBy';
COMMENT ON COLUMN data_asset.temporal_coverage IS 'ISO 8601 interval (MD temporalCoverage)';
COMMENT ON COLUMN data_asset.conforms_to IS 'Standard or schema (MD conformsTo)';
COMMENT ON COLUMN data_asset.access_rights IS 'Plus any handling caveat (MD accessRights)';
COMMENT ON COLUMN data_asset.licence IS 'Usually OGL v3.0 for open data (MD licence)';
COMMENT ON COLUMN data_asset.source_dataset IS 'The source data set when a distribution is designated (IDC)';
COMMENT ON COLUMN data_asset.next_review IS 'Within 12 months (DAM, IDC)';

CREATE TABLE role_assignment (
  assignment_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  role_type text CHECK (role_type IN ('Chief data officer', 'Lead data owner', 'Data owner', 'Data steward', 'Data custodian', 'Information asset owner', 'Process owner', 'Data analyst', 'Business analyst', 'Data user', 'Supplier')) NOT NULL,
  holder text NOT NULL,
  organisation text REFERENCES organisation(organisation_id),
  start_date date,
  end_date date,
  successor text
);
COMMENT ON TABLE role_assignment IS 'Who holds an accountability for an asset. Names are held only in the organisation''s own records.';
COMMENT ON COLUMN role_assignment.holder IS 'Named person, team or role; a named data owner is required by the DAM policy';
COMMENT ON COLUMN role_assignment.end_date IS 'When an owner leaves, a successor must be named';

CREATE TABLE distribution (
  distribution_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  title text,
  access_url text NOT NULL,
  media_type text
);
COMMENT ON TABLE distribution IS 'A file, API or other way the asset is made available.';
COMMENT ON COLUMN distribution.media_type IS 'IANA media type (MD mediaType)';

CREATE TABLE data_sharing_agreement (
  agreement_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  provider text REFERENCES organisation(organisation_id) NOT NULL,
  recipient text REFERENCES organisation(organisation_id) NOT NULL,
  reference text,
  quality_obligations text
);
COMMENT ON TABLE data_sharing_agreement IS 'An agreement under which an asset is provided to or acquired from another organisation.';
COMMENT ON COLUMN data_sharing_agreement.reference IS 'Agreement, MOU or legal gateway reference';
COMMENT ON COLUMN data_sharing_agreement.quality_obligations IS 'Quality responsibilities agreed with the supplier';

CREATE TABLE metadata_record (
  record_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  standard text NOT NULL,
  cda_coverage_pct numeric,
  profile text,
  conforms boolean,
  assessed_on date
);
COMMENT ON TABLE metadata_record IS 'A catalogue record describing the asset in a metadata standard, with its gap assessment.';
COMMENT ON COLUMN metadata_record.standard IS 'DCAT, schema.org, CKAN, GEMINI and so on';
COMMENT ON COLUMN metadata_record.cda_coverage_pct IS 'Share of the 13 critical data asset properties present';
COMMENT ON COLUMN metadata_record.profile IS 'Application profile checked, for example uk-cda';

CREATE TABLE data_item (
  item_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  name text NOT NULL,
  description text,
  personal_data boolean,
  lifecycle_stage text CHECK (lifecycle_stage IN ('Plan', 'Collect or acquire and ingest', 'Prepare, store and maintain', 'Use and process', 'Share and publish', 'Archive or destroy'))
);
COMMENT ON TABLE data_item IS 'A critical data item (field, table or element) within an asset.';
COMMENT ON COLUMN data_item.personal_data IS 'Personal data: accuracy is a legal duty (ICO)';
COMMENT ON COLUMN data_item.lifecycle_stage IS 'Where the item is captured or changed (GDQF-LC)';

CREATE TABLE user_need (
  need_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  user_group text NOT NULL,
  need text NOT NULL,
  dimension text CHECK (dimension IN ('completeness', 'uniqueness', 'consistency', 'timeliness', 'validity', 'accuracy', 'representativeness'))
);
COMMENT ON TABLE user_need IS 'A user group of the asset and what quality it needs.';

CREATE TABLE data_quality_action_plan (
  dqap_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  status text CHECK (status IN ('in_place', 'in_development', 'not_started', 'equivalent_mechanism')) NOT NULL,
  link text,
  measurement_frequency text,
  covers_all_seven_steps boolean,
  last_reviewed date,
  next_review date
);
COMMENT ON TABLE data_quality_action_plan IS 'The DQAP, or equivalent mechanism, for one asset; covers the 7 steps.';
COMMENT ON COLUMN data_quality_action_plan.link IS 'Where the plan is kept';
COMMENT ON COLUMN data_quality_action_plan.measurement_frequency IS 'ISO 8601 duration such as P1M';

CREATE TABLE quality_rule (
  rule_id text PRIMARY KEY,
  dqap text REFERENCES data_quality_action_plan(dqap_id) NOT NULL,
  description text NOT NULL,
  dimension text CHECK (dimension IN ('completeness', 'uniqueness', 'consistency', 'timeliness', 'validity', 'accuracy', 'representativeness')) NOT NULL,
  check_type text CHECK (check_type IN ('not_null', 'required_columns', 'unique', 'type', 'regex', 'in_set', 'range', 'not_future', 'compare', 'sum_max', 'freshness', 'no_gaps', 'header_has_unit', 'not_unknown', 'group_disparity', 'identifier', 'outlier')) NOT NULL,
  parameters text,
  method text,
  importance text CHECK (importance IN ('1 Low', '2 Medium', '3 High', '4 Critical')) NOT NULL,
  impact text CHECK (impact IN ('1 Low', '2 Medium', '3 High', '4 Critical')) NOT NULL,
  target_pct numeric NOT NULL,
  control_point text CHECK (control_point IN ('source', 'pipeline', 'reporting')),
  agreed_on date
);
COMMENT ON TABLE quality_rule IS 'A data quality rule with its dimension, method and agreed target.';
COMMENT ON COLUMN quality_rule.description IS 'Plain English';
COMMENT ON COLUMN quality_rule.parameters IS 'Check parameters (YAML or JSON)';
COMMENT ON COLUMN quality_rule.importance IS 'Importance of purpose 1 to 4 (IF)';
COMMENT ON COLUMN quality_rule.impact IS 'Impact of an issue 1 to 4 (IF)';
COMMENT ON COLUMN quality_rule.target_pct IS 'Within the issues framework range for importance x impact';
COMMENT ON COLUMN quality_rule.control_point IS 'Where the control belongs (GDQF-P3)';

CREATE TABLE measurement_run (
  run_id text PRIMARY KEY,
  dqap text REFERENCES data_quality_action_plan(dqap_id) NOT NULL,
  as_of date NOT NULL,
  rows_checked integer,
  rules_met integer,
  rules_total integer,
  trust_level text CHECK (trust_level IN ('Trustworthy', 'Usable with caveats', 'Use with care', 'Not fit for purpose')),
  is_baseline boolean
);
COMMENT ON TABLE measurement_run IS 'One assessment of an asset against its rules.';

CREATE TABLE rule_result (
  result_id text PRIMARY KEY,
  run text REFERENCES measurement_run(run_id) NOT NULL,
  rule text REFERENCES quality_rule(rule_id) NOT NULL,
  checked integer NOT NULL,
  passed integer NOT NULL,
  performance_pct numeric NOT NULL,
  meets_target boolean NOT NULL,
  band text CHECK (band IN ('high', 'middle', 'low', 'critical')),
  priority_score integer
);
COMMENT ON TABLE rule_result IS 'The result of one rule in one run.';
COMMENT ON COLUMN rule_result.priority_score IS 'Importance x impact x band score (IF)';

CREATE TABLE issue (
  issue_id text PRIMARY KEY,
  rule text REFERENCES quality_rule(rule_id) NOT NULL,
  raised_by_result text REFERENCES rule_result(result_id),
  issue_type text,
  raised_on date NOT NULL,
  priority text CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')) NOT NULL,
  resolution_timescale text,
  target_resolution_date date,
  actual_resolution_date date,
  review_date date,
  status text CHECK (status IN ('Open', 'In progress', 'Resolved', 'Accepted risk')) NOT NULL,
  cycles_open integer,
  recurring boolean,
  owner text REFERENCES role_assignment(assignment_id)
);
COMMENT ON TABLE issue IS 'A rule that misses its target, logged in the Data Issues Log.';
COMMENT ON COLUMN issue.issue_type IS 'From the Commons issue type vocabulary';
COMMENT ON COLUMN issue.resolution_timescale IS 'Immediately, or within 1, 3 or 6 measurements (IF)';

CREATE TABLE root_cause (
  cause_id text PRIMARY KEY,
  issue text REFERENCES issue(issue_id) NOT NULL,
  description text NOT NULL,
  systemic text CHECK (systemic IN ('Systemic', 'One-off', 'Not known yet')) NOT NULL,
  addressable boolean,
  options_considered text,
  cost_benefit text,
  lifecycle_stage text CHECK (lifecycle_stage IN ('Plan', 'Collect or acquire and ingest', 'Prepare, store and maintain', 'Use and process', 'Share and publish', 'Archive or destroy'))
);
COMMENT ON TABLE root_cause IS 'The cause of an issue, found by root cause analysis.';
COMMENT ON COLUMN root_cause.description IS 'For example from 5 whys';
COMMENT ON COLUMN root_cause.addressable IS 'Can the organisation fix it itself';

CREATE TABLE remediation_action (
  action_id text PRIMARY KEY,
  issue text REFERENCES issue(issue_id) NOT NULL,
  cause text REFERENCES root_cause(cause_id),
  action_type text CHECK (action_type IN ('Containment', 'Corrective', 'Preventive')) NOT NULL,
  description text NOT NULL,
  owner text REFERENCES role_assignment(assignment_id) NOT NULL,
  target_date date NOT NULL,
  review_date date NOT NULL,
  goal_pct numeric,
  success_measure text,
  status text CHECK (status IN ('Not started', 'In progress', 'Done', 'Blocked')) NOT NULL
);
COMMENT ON TABLE remediation_action IS 'An action to contain, correct or prevent an issue.';

CREATE TABLE escalation (
  escalation_id text PRIMARY KEY,
  issue text REFERENCES issue(issue_id) NOT NULL,
  escalated_on date NOT NULL,
  escalated_to text CHECK (escalated_to IN ('Chief data officer', 'Lead data owner', 'Data owner', 'Data steward', 'Data custodian', 'Information asset owner', 'Process owner', 'Data analyst', 'Business analyst', 'Data user', 'Supplier')) NOT NULL,
  outcome text
);
COMMENT ON TABLE escalation IS 'An issue escalated because it is overdue.';

CREATE TABLE communication_plan_entry (
  entry_id text PRIMARY KEY,
  dqap text REFERENCES data_quality_action_plan(dqap_id) NOT NULL,
  stakeholder_group text NOT NULL,
  what_they_need text,
  route text,
  frequency text,
  owner text REFERENCES role_assignment(assignment_id),
  last_sent date
);
COMMENT ON TABLE communication_plan_entry IS 'Who needs to know what about the asset''s quality, how and how often.';
COMMENT ON COLUMN communication_plan_entry.route IS 'Metadata, documentation, data sharing agreement, meeting';

CREATE TABLE quality_statement (
  statement_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  run text REFERENCES measurement_run(run_id),
  issued_on date NOT NULL,
  summary text NOT NULL,
  fit_for text,
  not_fit_for text,
  contact_route text
);
COMMENT ON TABLE quality_statement IS 'A plain English statement of an asset''s quality, strengths and limitations.';
COMMENT ON COLUMN quality_statement.contact_route IS 'A role or form, never a personal email';

CREATE TABLE asset_return (
  return_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  period text NOT NULL,
  dqap_status text CHECK (dqap_status IN ('in_place', 'in_development', 'not_started', 'equivalent_mechanism')),
  baseline_run text REFERENCES measurement_run(run_id),
  submitted_on date
);
COMMENT ON TABLE asset_return IS 'One asset''s row in the return to GDS.';

CREATE TABLE annual_review (
  review_id text PRIMARY KEY,
  asset text REFERENCES data_asset(asset_id) NOT NULL,
  reviewed_on date NOT NULL,
  still_critical boolean NOT NULL,
  owner_confirmed boolean NOT NULL,
  metadata_reviewed boolean NOT NULL,
  dqap_covers_seven_steps boolean,
  signed_off_by text CHECK (signed_off_by IN ('Chief data officer', 'Lead data owner', 'Data owner', 'Data steward', 'Data custodian', 'Information asset owner', 'Process owner', 'Data analyst', 'Business analyst', 'Data user', 'Supplier'))
);
COMMENT ON TABLE annual_review IS 'The yearly review of an asset, its owner, metadata and DQAP.';

CREATE TABLE requirement (
  requirement_id text PRIMARY KEY,
  source text NOT NULL,
  clause text,
  text text NOT NULL,
  strength text
);
COMMENT ON TABLE requirement IS 'A requirement from policy, guidance or a standard (the requirements register).';
COMMENT ON COLUMN requirement.strength IS 'must, should, method, principle';

CREATE TABLE maturity_assessment (
  assessment_id text PRIMARY KEY,
  organisation text REFERENCES organisation(organisation_id) NOT NULL,
  assessed_on date NOT NULL,
  theme text NOT NULL,
  level integer NOT NULL
);
COMMENT ON TABLE maturity_assessment IS 'An organisation''s self-assessed data quality maturity, by theme.';
COMMENT ON COLUMN maturity_assessment.level IS '1 Beginning to 5 Mastering';

CREATE TABLE data_asset_purposes (
  asset_id text NOT NULL REFERENCES data_asset(asset_id),
  value text NOT NULL CHECK (value IN ('Public service delivery', 'Legislative, legal or contractual requirement', 'Defence, national security and resilience', 'Policy development and evaluation', 'Official statistics', 'Public interest', 'Fraud and error')),
  PRIMARY KEY (asset_id, value)
);
COMMENT ON TABLE data_asset_purposes IS 'Links DataAsset to its purposes.';

CREATE TABLE quality_rule_data_items (
  rule_id text NOT NULL REFERENCES quality_rule(rule_id),
  data_item_item_id text NOT NULL REFERENCES data_item(item_id),
  PRIMARY KEY (rule_id, data_item_item_id)
);
COMMENT ON TABLE quality_rule_data_items IS 'Links QualityRule to its data items.';
